examples.mysql:
SELECT COUNT(*)                    AS orders,
       COUNT(DISTINCT customer_id) AS buyers
FROM orders;

examples.tsql:
SELECT COUNT(*)                    AS orders,
       COUNT(DISTINCT customer_id) AS buyers
FROM orders;

examples.mysql:
SELECT AVG(salary)              AS avg_ignoring_null,
       AVG(COALESCE(salary, 0)) AS avg_null_as_zero
FROM employees;

examples.tsql:
SELECT AVG(salary * 1.0)              AS avg_ignoring_null,
       AVG(COALESCE(salary, 0) * 1.0) AS avg_null_as_zero
FROM employees;
